// ─── File: ExpandDemo.java ───
package com.bank.expand;

import java.util.logging.*;

public class ExpandDemo {
    private static final Logger log = Logger.getLogger("Expand");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Vpc vpc = new Vpc("vpc-0abc", "10.0.0.0/16");
        Subnet oldSubnet = vpc.createSubnet("subnet-app-old", "10.0.1.0/24"); // 251 usable
        oldSubnet.consume(251);  // fully exhausted

        // Attempt the forbidden in-place resize.
        try {
            oldSubnet.resize("10.0.0.0/23");
        } catch (UnsupportedOperationException e) {
            log.warning(() -> "In-place resize blocked: " + e.getMessage());
        }

        // Supported path: secondary CIDR + new larger subnet + gradual migration.
        vpc.associateSecondaryCidr("100.64.0.0/16");
        Subnet newSubnet = vpc.createSubnet("subnet-app-new", "100.64.0.0/20"); // ~4091 usable

        MigrationPlan plan = new MigrationPlan(oldSubnet, newSubnet);
        plan.migrateBatch(100);  // move 100 pods/instances
        plan.migrateBatch(151);
        log.info(() -> "Migration status: " + plan.status());
    }
}

// ─── Would be in Subnet.java ───
class Subnet {
    final String id, cidr; private int used; private final int capacity;
    Subnet(String id, String cidr) {
        this.id = id; this.cidr = cidr;
        int prefix = Integer.parseInt(cidr.split("/")[1]);
        this.capacity = (int) Math.pow(2, 32 - prefix) - 5;  // AWS reserves 5
    }
    void consume(int n) { used += n; }
    void release(int n) { used = Math.max(0, used - n); }
    int remaining() { return capacity - used; }
    void resize(String newCidr) {
        throw new UnsupportedOperationException(
            "subnet CIDR is immutable — associate a secondary VPC CIDR and migrate instead");
    }
}

// ─── Would be in Vpc.java ───
class Vpc {
    final String id; private final java.util.List<String> cidrs = new java.util.ArrayList<>();
    Vpc(String id, String primaryCidr) { this.id = id; cidrs.add(primaryCidr); }
    void associateSecondaryCidr(String cidr) { cidrs.add(cidr); }   // VPC can hold several
    Subnet createSubnet(String id, String cidr) { return new Subnet(id, cidr); }
}

// ─── Would be in MigrationPlan.java ───
class MigrationPlan {
    private final Subnet from, to; private int moved;
    MigrationPlan(Subnet from, Subnet to) { this.from = from; this.to = to; }
    void migrateBatch(int n) {        // drain old, fill new — no renumber of live IFs
        from.release(n); to.consume(n); moved += n;
    }
    String status() {
        return moved + " workloads migrated; old remaining=" + from.remaining()
             + ", new remaining=" + to.remaining();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
